INSERT INTO repo_subtopics (subtopic_id, name, subtopic_no, description, subtopic_sd_id, review_status, status, version) VALUES ('SUB_COURSE_035_M2_S4', 'tolerancing', '4', 'tolerancing: Specifying allowable variation in a dimension or geometric characteristic so parts can be manufactured and assembled reliably. In Computer-Aided Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of tolerancing within CAD/CAM, particularly where the Computer-Aided Design module establishes its technical context.', 'SSD_COURSE_035_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M2_S5', 'design documentation', '5', 'design documentation: Structured drawings, models, annotations, specifications, and related records used to communicate and control a product design. In Computer-Aided Design, the focus is on the analysis, design, implementation, interpretation, or evaluation of design documentation within CAD/CAM, particularly where the Computer-Aided Design module establishes its technical context.', 'SSD_COURSE_035_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M3_S1', 'sectioning', '1', 'sectioning: Creating sectional views or cuts to reveal internal geometry in an engineering drawing or model. In Engineering Graphics and Product Definition, the focus is on the analysis, design, implementation, interpretation, or evaluation of sectioning within CAD/CAM, particularly where the Engineering Graphics and Product Definition module establishes its technical context.', 'SSD_COURSE_035_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M3_S2', 'dimensioning', '2', 'dimensioning: Communicating the sizes and locations of geometric features using standard engineering drawing conventions. In Engineering Graphics and Product Definition, the focus is on the analysis, design, implementation, interpretation, or evaluation of dimensioning within CAD/CAM, particularly where the Engineering Graphics and Product Definition module establishes its technical context.', 'SSD_COURSE_035_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M3_S3', 'geometric dimensioning and tolerancing', '3', 'geometric dimensioning and tolerancing refers to a system for specifying allowable geometric variation, datum references, and feature requirements on engineering drawings or models. In Engineering Graphics and Product Definition, the focus is on the analysis, design, implementation, interpretation, or evaluation of geometric dimensioning and tolerancing within CAD/CAM, particularly where the Engineering Graphics and Product Definition module establishes its technical context.', 'SSD_COURSE_035_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M3_S4', 'bills of materials', '4', 'bills of materials: Structured lists of the parts, assemblies, quantities, and identifiers required to build a product. In Engineering Graphics and Product Definition, the focus is on the analysis, design, implementation, interpretation, or evaluation of bills of materials within CAD/CAM, particularly where the Engineering Graphics and Product Definition module establishes its technical context.', 'SSD_COURSE_035_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M4_S1', 'process planning', '1', 'process planning: Determining the sequence of manufacturing operations, machines, tools, fixtures, and parameters required to produce a component. In Manufacturing Planning, the focus is on the analysis, design, implementation, interpretation, or evaluation of process planning within CAD/CAM, particularly where the Manufacturing Planning module establishes its technical context.', 'SSD_COURSE_035_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M4_S2', 'Manufacturing routing', '2', 'Manufacturing routing: Definition and sequencing of the manufacturing operations, work centres, tools, setups, and process parameters required to produce a part or product. In Manufacturing Planning, the focus is on curricular scope: CAD/CAM; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_035_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M4_S3', 'tooling', '3', 'tooling: Fixtures, cutting tools, dies, moulds, and related equipment used to manufacture a component. In Manufacturing Planning, the focus is on the analysis, design, implementation, interpretation, or evaluation of tooling within CAD/CAM, particularly where the Manufacturing Planning module establishes its technical context.', 'SSD_COURSE_035_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M4_S4', 'setup planning', '4', 'setup planning: Determining how a workpiece will be located, oriented, supported, and processed for a manufacturing setup. In Manufacturing Planning, the focus is on the analysis, design, implementation, interpretation, or evaluation of setup planning within CAD/CAM, particularly where the Manufacturing Planning module establishes its technical context.', 'SSD_COURSE_035_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M4_S5', 'computer-aided process planning', '5', 'computer-aided process planning: Computer-supported generation or selection of manufacturing process plans from product and production information. In Manufacturing Planning, the focus is on the analysis, design, implementation, interpretation, or evaluation of computer-aided process planning within CAD/CAM, particularly where the Manufacturing Planning module establishes its technical context.', 'SSD_COURSE_035_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M5_S1', 'coordinate systems', '1', 'coordinate systems: Reference frames used to define the position and orientation of geometry, tools, machines, or workpieces. In CNC Programming and Machining, the focus is on the analysis, design, implementation, interpretation, or evaluation of coordinate systems within CAD/CAM, particularly where the CNC Programming and Machining module establishes its technical context.', 'SSD_COURSE_035_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M5_S2', 'G-code', '2', 'G-code: Machine-control instructions used by CNC equipment to specify movements, speeds, feeds, and related operations. In CNC Programming and Machining, the focus is on the analysis, design, implementation, interpretation, or evaluation of G-code within CAD/CAM, particularly where the CNC Programming and Machining module establishes its technical context.', 'SSD_COURSE_035_M5_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M5_S3', 'tool paths', '3', 'tool paths: Planned trajectories followed by a cutting tool during CNC machining. In CNC Programming and Machining, the focus is on the analysis, design, implementation, interpretation, or evaluation of tool paths within CAD/CAM, particularly where the CNC Programming and Machining module establishes its technical context.', 'SSD_COURSE_035_M5_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M5_S4', 'interpolation', '4', 'interpolation: Calculation of intermediate tool positions between programmed points to produce a required CNC motion. In CNC Programming and Machining, the focus is on the analysis, design, implementation, interpretation, or evaluation of interpolation within CAD/CAM, particularly where the CNC Programming and Machining module establishes its technical context.', 'SSD_COURSE_035_M5_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M5_S5', 'machining simulation', '5', 'machining simulation: Computer-based prediction and visualisation of tool motion, material removal, collisions, and machining results. In CNC Programming and Machining, the focus is on the analysis, design, implementation, interpretation, or evaluation of machining simulation within CAD/CAM, particularly where the CNC Programming and Machining module establishes its technical context.', 'SSD_COURSE_035_M5_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M6_S1', 'CAM workflows', '1', 'CAM workflows refers to the sequence from manufacturing-process planning through tool-path creation, verification, post-processing, and CNC execution. In Computer-Aided Manufacturing, the focus is on the analysis, design, implementation, interpretation, or evaluation of CAM workflows within CAD/CAM, particularly where the Computer-Aided Manufacturing module establishes its technical context.', 'SSD_COURSE_035_M6_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M6_S2', 'tool-path generation', '2', 'tool-path generation: Computing machining trajectories from part geometry, cutting tools, stock, and process parameters. In Computer-Aided Manufacturing, the focus is on the analysis, design, implementation, interpretation, or evaluation of tool-path generation within CAD/CAM, particularly where the Computer-Aided Manufacturing module establishes its technical context.', 'SSD_COURSE_035_M6_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M6_S3', 'verification', '3', 'verification: Process of determining whether a model, design, implementation, or manufactured result satisfies specified requirements or has been constructed correctly. In Computer-Aided Manufacturing, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_035_M6_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M6_S4', 'post-processing', '4', 'post-processing: Converting CAM tool paths into machine-specific CNC instructions for a particular controller. In Computer-Aided Manufacturing, the focus is on the analysis, design, implementation, interpretation, or evaluation of post-processing within CAD/CAM, particularly where the Computer-Aided Manufacturing module establishes its technical context.', 'SSD_COURSE_035_M6_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M6_S5', 'machining optimization', '5', 'machining optimization: Selecting tool paths and process parameters to balance productivity, surface quality, tool life, and machining constraints. In Computer-Aided Manufacturing, the focus is on the analysis, design, implementation, interpretation, or evaluation of machining optimization within CAD/CAM, particularly where the Computer-Aided Manufacturing module establishes its technical context.', 'SSD_COURSE_035_M6_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M7_S1', 'associativity', '1', 'associativity: Maintaining links so changes to related CAD geometry, features, drawings, or manufacturing data can propagate consistently. In CAD/CAM Integration and Product Data, the focus is on the analysis, design, implementation, interpretation, or evaluation of associativity within CAD/CAM, particularly where the CAD/CAM Integration and Product Data module establishes its technical context.', 'SSD_COURSE_035_M7_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M7_S2', 'product data exchange', '2', 'product data exchange: Transferring product geometry and engineering information between different CAD/CAM systems using defined data formats. In CAD/CAM Integration and Product Data, the focus is on the analysis, design, implementation, interpretation, or evaluation of product data exchange within CAD/CAM, particularly where the CAD/CAM Integration and Product Data module establishes its technical context.', 'SSD_COURSE_035_M7_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M7_S3', 'Product Lifecycle Management (PLM)', '3', 'PLM: Product Lifecycle Management, the controlled management of product information and processes from design through manufacture, service, and retirement. In CAD/CAM Integration and Product Data, the focus is on the analysis, design, implementation, interpretation, or evaluation of PLM within CAD/CAM, particularly where the CAD/CAM Integration and Product Data module establishes its technical context.', 'SSD_COURSE_035_M7_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M7_S4', 'digital thread', '4', 'digital thread refers to a connected flow of product and process information across design, manufacturing, operation, and lifecycle stages. In CAD/CAM Integration and Product Data, the focus is on the analysis, design, implementation, interpretation, or evaluation of digital thread within CAD/CAM, particularly where the CAD/CAM Integration and Product Data module establishes its technical context.', 'SSD_COURSE_035_M7_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_035_M7_S5', 'model-based definition', '5', 'model-based definition: Using a 3D digital product model as the authoritative source for geometry, dimensions, tolerances, and manufacturing information. In CAD/CAM Integration and Product Data, the focus is on the analysis, design, implementation, interpretation, or evaluation of model-based definition within CAD/CAM, particularly where the CAD/CAM Integration and Product Data module establishes its technical context.', 'SSD_COURSE_035_M7_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M1_S1', 'measurement principles', '1', 'measurement principles: Principles governing how a physical quantity is defined, measured, represented, and related to an indicated value and measurement uncertainty. In Sensors and Transducers, the focus is on the analysis, design, implementation, interpretation, or evaluation of measurement principles within Mechatronics, particularly where the Sensors and Transducers module establishes its technical context.', 'SSD_COURSE_036_M1_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M1_S2', 'position', '2', 'position refers to the measured or commanded location of a mechanical component or actuator along a defined coordinate. In Sensors and Transducers, the focus is on the analysis, design, implementation, interpretation, or evaluation of position within Mechatronics, particularly where the Sensors and Transducers module establishes its technical context.', 'SSD_COURSE_036_M1_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M1_S3', 'velocity', '3', 'velocity refers to the rate of change of position of a mechanical component with time. In Sensors and Transducers, the focus is on the analysis, design, implementation, interpretation, or evaluation of velocity within Mechatronics, particularly where the Sensors and Transducers module establishes its technical context.', 'SSD_COURSE_036_M1_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M1_S4', 'force', '4', 'force refers to an interaction that produces acceleration or deformation and is measured or controlled in mechatronic systems. In Sensors and Transducers, the focus is on the analysis, design, implementation, interpretation, or evaluation of force within Mechatronics, particularly where the Sensors and Transducers module establishes its technical context.', 'SSD_COURSE_036_M1_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M1_S5', 'pressure', '5', 'pressure: Normal force per unit area acting on a surface or within a fluid; in continuum fluid mechanics it is a scalar state variable whose spatial gradients can drive flow. In Sensors and Transducers, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_036_M1_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M1_S6', 'temperature sensing', '6', 'temperature sensing: Measurement of temperature using a sensor whose output changes predictably with temperature. In Sensors and Transducers, the focus is on the analysis, design, implementation, interpretation, or evaluation of temperature sensing within Mechatronics, particularly where the Sensors and Transducers module establishes its technical context.', 'SSD_COURSE_036_M1_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M2_S1', 'DC motors', '1', 'DC motors: Electric motors that convert direct-current electrical input into controlled rotary mechanical motion. In Actuators and Drives, the focus is on the analysis, design, implementation, interpretation, or evaluation of DC motors within Mechatronics, particularly where the Actuators and Drives module establishes its technical context.', 'SSD_COURSE_036_M2_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M2_S2', 'stepper motors', '2', 'stepper motors: Motors that move in discrete angular steps in response to commanded electrical sequences. In Actuators and Drives, the focus is on the analysis, design, implementation, interpretation, or evaluation of stepper motors within Mechatronics, particularly where the Actuators and Drives module establishes its technical context.', 'SSD_COURSE_036_M2_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M2_S3', 'servo drives', '3', 'servo drives: Closed-loop drive systems that regulate motor position, speed, or torque using feedback. In Actuators and Drives, the focus is on the analysis, design, implementation, interpretation, or evaluation of servo drives within Mechatronics, particularly where the Actuators and Drives module establishes its technical context.', 'SSD_COURSE_036_M2_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M2_S4', 'solenoids', '4', 'solenoids: Electromagnetic actuators that produce linear motion when their coil is energised. In Actuators and Drives, the focus is on the analysis, design, implementation, interpretation, or evaluation of solenoids within Mechatronics, particularly where the Actuators and Drives module establishes its technical context.', 'SSD_COURSE_036_M2_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M2_S5', 'pneumatic and hydraulic actuators', '5', 'pneumatic and hydraulic actuators: Actuators that convert compressed air or pressurised fluid into controlled mechanical motion. In Actuators and Drives, the focus is on the analysis, design, implementation, interpretation, or evaluation of pneumatic and hydraulic actuators within Mechatronics, particularly where the Actuators and Drives module establishes its technical context.', 'SSD_COURSE_036_M2_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M3_S1', 'microcontrollers', '1', 'microcontrollers: Integrated programmable devices that combine a processor, memory, and peripheral interfaces for dedicated control and embedded-system tasks. In Embedded Controllers, the focus is on the analysis, design, implementation, interpretation, or evaluation of microcontrollers within Mechatronics, particularly where the Embedded Controllers module establishes its technical context.', 'SSD_COURSE_036_M3_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M3_S2', 'Input/Output (I/O)', '2', 'I/O: Input/output interfaces through which a controller exchanges signals with sensors, actuators, and other devices. In Embedded Controllers, the focus is on the analysis, design, implementation, interpretation, or evaluation of I/O within Mechatronics, particularly where the Embedded Controllers module establishes its technical context.', 'SSD_COURSE_036_M3_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M3_S3', 'timers', '3', 'timers: Controller hardware or software functions that generate timing events, delays, or periodic operations. In Embedded Controllers, the focus is on the analysis, design, implementation, interpretation, or evaluation of timers within Mechatronics, particularly where the Embedded Controllers module establishes its technical context.', 'SSD_COURSE_036_M3_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M3_S4', 'interrupts', '4', 'interrupts: Signals that temporarily divert processor execution to handle an event requiring timely service. In Embedded Controllers, the focus is on the analysis, design, implementation, interpretation, or evaluation of interrupts within Mechatronics, particularly where the Embedded Controllers module establishes its technical context.', 'SSD_COURSE_036_M3_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M3_S5', 'Analog-to-Digital / Digital-to-Analog Conversion (ADC/DAC)', '5', 'ADC/DAC: Analog-to-digital and digital-to-analog conversion processes used to interface continuous-valued signals with digital systems. In Embedded Controllers, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_036_M3_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M3_S6', 'real-time execution', '6', 'real-time execution: Execution in which computations must complete within defined timing deadlines. In Embedded Controllers, the focus is on the analysis, design, implementation, interpretation, or evaluation of real-time execution within Mechatronics, particularly where the Embedded Controllers module establishes its technical context.', 'SSD_COURSE_036_M3_S6', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M4_S1', 'amplification', '1', 'amplification: Increase in the magnitude of a signal or physical quantity using an active or passive mechanism, subject to gain, bandwidth, distortion, noise, and stability constraints. In Signal Conditioning and Data Acquisition, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_036_M4_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M4_S2', 'filtering', '2', 'filtering: Selective attenuation or passage of signal components according to frequency, time, spatial characteristics, or other defined criteria. In Signal Conditioning and Data Acquisition, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_036_M4_S2', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M4_S3', 'Measurement isolation', '3', 'Measurement isolation: Electrical or functional isolation used to prevent unwanted conductive interaction between signal paths, measurement circuits, or system elements while preserving the required transfer of information or energy. In Signal Conditioning and Data Acquisition, the focus is on curricular scope: Mechatronics; Electrical Measurements and Instrumentation; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_036_M4_S3', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M4_S4', 'Signal sampling', '4', 'Signal sampling: Conversion of a continuous-time signal into discrete samples at specified sampling instants; sampling rate and reconstruction requirements determine aliasing and information loss. In Signal Conditioning and Data Acquisition, the focus is on curricular scope: Mechatronics; Electrical Measurements and Instrumentation; The concept is represented at the level of the stated mechanism, properties, constraints, and application criteria.', 'SSD_COURSE_036_M4_S4', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M4_S5', 'data acquisition', '5', 'data acquisition: Measurement, conditioning, conversion, and collection of sensor signals for digital processing or control. In Signal Conditioning and Data Acquisition, the focus is on the analysis, design, implementation, interpretation, or evaluation of data acquisition within Mechatronics, particularly where the Signal Conditioning and Data Acquisition module establishes its technical context.', 'SSD_COURSE_036_M4_S5', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M5_S1', 'dynamic models', '1', 'dynamic models: Mathematical models describing how a system''s states and outputs change with time. In System Modelling and Control, the focus is on the analysis, design, implementation, interpretation, or evaluation of dynamic models within Mechatronics, particularly where the System Modelling and Control module establishes its technical context.', 'SSD_COURSE_036_M5_S1', 'Semantically_Audited', 'Active', '4.0'), ('SUB_COURSE_036_M5_S2', 'transfer functions', '2', 'transfer functions: Mathematical representations relating the output to the input of a linear time-invariant system in a transform domain under stated initial-condition assumptions. In System Modelling and Control, the focus is on concept-level scope: the defining mechanism, properties, constraints, and application criteria; curricular context is recorded in Concept_Category and Typical_Modules.', 'SSD_COURSE_036_M5_S2', 'Semantically_Audited', 'Active', '4.0') ON CONFLICT DO NOTHING;